"""Regenerate xid_ranges.inc from https://www.unicode.org/Public/18.0.0/ucd/UCD.zip."""

import hashlib
import sys
import zipfile
from pathlib import Path


def generate(archive):
    if hashlib.sha256(archive.read_bytes()).hexdigest() != "7b3e555514060b92290d154f53655c5eb0fa62b16eb04c03434ff72d1a66a0d8":
        raise ValueError("Expected the Unicode 18.0.0 UCD.zip")
    with zipfile.ZipFile(archive) as ucd:
        properties = ucd.read("DerivedCoreProperties.txt").decode("utf-8")

    # XID_Start is a subset of XID_Continue. Combine the two properties so
    # the scanner needs only one range lookup per non-ASCII scalar.
    classes = bytearray(0x110000)
    for line in properties.splitlines():
        fields = line.partition("#")[0].strip().split(";")
        if len(fields) != 2:
            continue
        interval, prop = (field.strip() for field in fields)
        if prop not in ("XID_Start", "XID_Continue"):
            continue
        first, _, last = interval.partition("..")
        for scalar in range(int(first, 16), int(last or first, 16) + 1):
            classes[scalar] |= 2 if prop == "XID_Start" else 1

    lines = ["// SPDX-License-Identifier: Unicode-3.0",
             "// Unicode 18.0.0. Generated by generate_xid.py from DerivedCoreProperties.txt."]
    start = 0
    for end in range(1, len(classes) + 1):
        if end < len(classes) and classes[end] == classes[start]:
            continue
        if classes[start]:
            assert classes[start] in (1, 3)
            can_start = "true" if classes[start] == 3 else "false"
            lines.append(f"{{ 0x{start:X}, 0x{end - 1:X}, {can_start} }},")
        start = end
    Path(__file__).with_name("xid_ranges.inc").write_bytes(("\n".join(lines) + "\n").encode("ascii"))


if __name__ == "__main__":
    generate(Path(sys.argv[1]))
